// Overview: reads the crowd README (generated by analysis.py) and renders
// its statistics, tables and figures on the home page.
const CROWD_REPO_URL = 'https://github.com/crowd-dataset/crowd';
const CROWD_RAW_BASE = 'https://raw.githubusercontent.com/crowd-dataset/crowd/main/';
const README_URL = `${CROWD_RAW_BASE}README.md`;

const ROAD_USERS = [
  { key: 'persons', label: 'Persons', column: 'Persons / min', color: 'var(--series-1)' },
  { key: 'cars', label: 'Cars', column: 'Cars / min', color: 'var(--series-2)' },
  { key: 'bicycles', label: 'Bicycles', column: 'Bicycles / min', color: 'var(--series-3)' },
  { key: 'motorcycles', label: 'Motorcycles', column: 'Motorcycles / min', color: 'var(--series-4)' },
  { key: 'buses', label: 'Buses', column: 'Buses / min', color: 'var(--series-5)' },
  { key: 'trucks', label: 'Trucks', column: 'Trucks / min', color: 'var(--series-6)' },
];


const overview = {
  visibleFigures: [],
  dialogIndex: 0,
  countries: null,
  countrySort: { column: 0, ascending: true },
};

const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function byId(id) {
  return document.getElementById(id);
}

function el(tag, attributes = {}, children = []) {
  const node = document.createElement(tag);
  Object.entries(attributes).forEach(([key, value]) => {
    if (value === undefined || value === null || value === false) return;
    if (key === 'className') node.className = value;
    else if (key === 'text') node.textContent = value;
    else if (key === 'style') node.style.cssText = value;
    else node.setAttribute(key, value === true ? '' : value);
  });
  [].concat(children).forEach((child) => {
    if (child === undefined || child === null) return;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  });
  return node;
}

function parseNumber(text) {
  const number = Number(String(text ?? '').replace(/[^\d.-]/g, ''));
  return Number.isFinite(number) ? number : 0;
}

function formatNumber(value, decimals = 0) {
  return value.toLocaleString('en-GB', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

function formatCompact(value) {
  if (value >= 1e6) return `${formatNumber(value / 1e6, 1)}M`;
  if (value >= 1e4) return `${formatNumber(value / 1e3, 0)}k`;
  return formatNumber(value);
}

// Bold, italics and links: the only Markdown the README captions use.
function appendInlineMarkdown(node, text) {
  const pattern = /(\*\*[^*]+\*\*|\*[^*]+\*|\[[^\]]+\]\([^)]+\)|`[^`]+`)/g;
  let lastIndex = 0;
  for (const match of text.matchAll(pattern)) {
    node.append(text.slice(lastIndex, match.index));
    const token = match[0];
    if (token.startsWith('**')) node.append(el('strong', { text: token.slice(2, -2) }));
    else if (token.startsWith('*')) node.append(el('em', { text: token.slice(1, -1) }));
    else if (token.startsWith('`')) node.append(el('code', { text: token.slice(1, -1) }));
    else {
      const [, label, url] = token.match(/\[([^\]]+)\]\(([^)]+)\)/);
      if (/^https?:\/\//.test(url)) node.append(el('a', { href: url, target: '_blank', rel: 'noreferrer noopener', text: label }));
      else node.append(label);
    }
    lastIndex = match.index + token.length;
  }
  node.append(text.slice(lastIndex));
  return node;
}

// ---- README parsing -------------------------------------------------------

function parseStats(markdown) {
  const start = markdown.indexOf('<!-- dataset-stats:start -->');
  const end = markdown.indexOf('## ', markdown.indexOf('<details', start));
  const block = markdown.slice(start, end > start ? end : undefined);
  const field = (label) => block.match(new RegExp(`\\*\\*${label}[^*]*\\*\\*([^\\n]*)`))?.[1]?.trim() ?? '';

  const footage = field('Footage:');
  const videos = field('Videos:');
  const objects = field('Detected objects');
  const detections = {};
  for (const match of objects.matchAll(/([\d,]+)\s+(persons|cars|bicycles|motorcycles|buses|trucks)/g)) {
    detections[match[2]] = parseNumber(match[1]);
  }

  return {
    hours: parseNumber(footage.split('hours')[0]),
    days: parseNumber(footage.match(/\(([\d,.]+) days\)/)?.[1]),
    videos: parseNumber(videos.match(/([\d,]+) unique videos/)?.[1]),
    segments: parseNumber(videos.match(/([\d,]+) segments/)?.[1]),
    localities: parseNumber(field('Localities')),
    countries: parseNumber(field('Countries and territories:')),
    continents: parseNumber(field('Continents:')),
    yoloSegments: parseNumber(field('YOLO detections:').match(/([\d,]+)/)?.[1]),
    detections,
    updated: field('Last updated:'),
  };
}

function splitRow(line) {
  return line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((cell) => cell.trim());
}

function parseTableAfter(markdown, marker) {
  const start = markdown.indexOf(marker);
  if (start < 0) return null;
  const lines = markdown.slice(start).split('\n');
  const first = lines.findIndex((line) => line.trim().startsWith('|'));
  if (first < 0) return null;
  const tableLines = [];
  for (let index = first; index < lines.length && lines[index].trim().startsWith('|'); index += 1) {
    tableLines.push(lines[index]);
  }
  const [header, , ...rows] = tableLines;
  return { headers: splitRow(header), rows: rows.map(splitRow) };
}

function tableColumn(table, name) {
  return table.headers.indexOf(name);
}

// README captions also explain the interactive HTML charts ("In the HTML version, click…");
// the page shows only what a figure says.
function withoutUsageNotes(caption) {
  return caption
    .replace(/\s*\([^()]*HTML version[^()]*\)/gi, '')
    .split(/(?<=[.;])\s+/)
    .filter((sentence) => !/HTML version|\bclick\b|\bhover\b|\bscroll\b/i.test(sentence))
    .join(' ')
    .replace(/;\s*$/, '.');
}

function parseFigures(markdown) {
  const detectionsStart = markdown.indexOf('## Detections in the footage');
  const addingStart = markdown.indexOf('## Adding videos');
  const contributorsStart = markdown.indexOf('## Who added the videos');
  const pattern = /\[!\[([^\]]*)\]\((figures\/([^)]+)\.png)\)\]\(([^)]+)\)[^\n]*\n?([^\n]*)/g;
  const figures = [];

  for (const match of markdown.matchAll(pattern)) {
    const [, alt, path, name, interactiveUrl, nextLine] = match;
    let section = 'coverage';
    if (match.index > contributorsStart && contributorsStart > 0) section = 'channels';
    else if (match.index > detectionsStart && (addingStart < 0 || match.index < addingStart)) section = 'road-users';

    const caption = withoutUsageNotes(nextLine.trim() && !nextLine.trim().startsWith('[![') && !nextLine.trim().startsWith('<!--')
      ? nextLine.trim()
      : alt);
    const title = alt.split(/ \(|: /)[0].replace(/[.:]$/, '');
    figures.push({ name, title, caption, section, image: CROWD_RAW_BASE + path, interactiveUrl });
  }

  return figures;
}

// ---- Hero ----------------------------------------------------------------

function renderLiveStats(stats) {
  const container = byId('statsGrid');
  const totalObjects = Object.values(stats.detections).reduce((sum, value) => sum + value, 0);
  const cards = [
    { value: stats.hours, label: 'Hours of driving', decimals: 0 },
    { value: stats.videos, label: 'Unique videos' },
    { value: stats.segments, label: 'Segments' },
    { value: stats.localities, label: 'Cities and towns' },
    { value: stats.countries, label: 'Countries and territories' },
    { value: totalObjects, label: 'Road users tracked', compact: true },
  ].filter((card) => card.value > 0);

  container.dataset.live = 'true';
  container.replaceChildren(...cards.map((card) => el('div', { className: 'stat-card' }, [
    el('div', { className: 'stat-value', 'data-count': card.value, 'data-compact': card.compact ? 'true' : null, text: card.compact ? formatCompact(card.value) : formatNumber(card.value) }),
    el('div', { className: 'stat-label', text: card.label }),
  ])));

  // One more number arrives separately, from the citation index (assets/citations.js).
  citingWorks.then((works) => {
    if (!works || !works.length) return;
    const card = el('div', { className: 'stat-card' }, [
      el('div', { className: 'stat-value', 'data-count': works.length, text: formatNumber(works.length) }),
      el('div', { className: 'stat-label', text: 'Citing publications' }),
    ]);
    container.append(card);
    observeCount(card.querySelector('[data-count]'));
  });

  const days = stats.days ? `That is ${formatNumber(stats.days, 0)} days of non-stop driving. ` : '';
  byId('liveNote').textContent = days.trim();

  // The headline in the hero reads these too.
  const setHero = (id, text) => { if (byId(id)) byId(id).textContent = text; };
  if (stats.hours) setHero('heroHours', formatNumber(stats.hours));
  if (stats.localities) setHero('heroCities', formatNumber(stats.localities));
  if (stats.countries) setHero('heroCountries', formatNumber(stats.countries));
  if (totalObjects) setHero('heroObjects', `${formatNumber(Math.floor(totalObjects / 1e6))} million`);
  container.querySelectorAll('[data-count]').forEach(observeCount);
}

function observeCount(node) {
  if (prefersReducedMotion || !('IntersectionObserver' in window)) return;
  const target = Number(node.dataset.count);
  const compact = node.dataset.compact === 'true';
  const observer = new IntersectionObserver((entries) => {
    if (!entries.some((entry) => entry.isIntersecting)) return;
    observer.disconnect();
    const duration = 1400;
    const render = (value) => {
      node.textContent = compact ? formatCompact(value) : formatNumber(Math.round(value));
    };
    let startTime = null;
    let done = false;
    const step = (now) => {
      if (done) return;
      if (startTime === null) startTime = now;
      const progress = Math.min(Math.max((now - startTime) / duration, 0), 1);
      render(target * (1 - (1 - progress) ** 3));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
    // Background tabs pause animation frames; make sure the final number lands.
    window.setTimeout(() => {
      done = true;
      render(target);
    }, duration + 300);
  }, { threshold: 0.4 });
  observer.observe(node);
}

// ---- Road users ------------------------------------------------------------

function renderDetections(stats, continentTable, markdown) {
  const grid = byId('detectionGrid');
  grid.replaceChildren(...ROAD_USERS.map((user) => {
    const value = stats.detections[user.key] || 0;
    return el('div', { className: 'detection-card', style: `--swatch: ${user.color}` }, [
      el('span', { className: 'detection-swatch', 'aria-hidden': 'true' }),
      el('div', { className: 'detection-value', 'data-count': value, 'data-compact': 'true', text: formatCompact(value) }),
      el('div', { className: 'detection-label', text: user.label }),
    ]);
  }));
  grid.querySelectorAll('[data-count]').forEach(observeCount);

  const basis = markdown.match(/Based on the YOLO detections in ([\d,]+) processed segments/)?.[1];
  if (basis) {
    byId('detectionIntro').textContent = `Unique objects tracked by YOLO11x (confidence of at least 0.7) in ${basis} processed segments. These are automatic detections, not hand-checked labels.`;
  }

  if (continentTable) renderMixChart(continentTable);
}

function renderMixChart(table) {
  const nameColumn = tableColumn(table, 'Continent');
  const hoursColumn = tableColumn(table, 'Analysed (h)');
  const rows = table.rows.map((row) => ({
    name: row[nameColumn],
    hours: row[hoursColumn],
    values: ROAD_USERS.map((user) => parseNumber(row[tableColumn(table, user.column)])),
  }));
  const max = Math.max(...rows.map((row) => row.values.reduce((sum, value) => sum + value, 0)));

  byId('mixLegend').replaceChildren(...ROAD_USERS.map((user) => el('span', { className: 'legend-item' }, [
    el('span', { className: 'legend-swatch', style: `background: ${user.color}` }),
    user.label,
  ])));

  const tooltip = el('div', { className: 'viz-tooltip', role: 'status', hidden: true });
  const chart = byId('mixChart');
  chart.replaceChildren(...rows.map((row) => {
    const total = row.values.reduce((sum, value) => sum + value, 0);
    const bar = el('div', { className: 'mix-bar', style: `width: ${(total / max) * 100}%` }, row.values.map((value, index) => {
      const segment = el('span', {
        className: 'mix-segment',
        style: `flex-grow: ${value}; background: ${ROAD_USERS[index].color}`,
        tabindex: '0',
        'aria-label': `${row.name}: ${formatNumber(value, 2)} ${ROAD_USERS[index].label.toLowerCase()} per minute`,
      });
      const show = (event) => {
        tooltip.replaceChildren(
          el('strong', { text: row.name }),
          el('span', { className: 'tooltip-row' }, [
            el('span', { className: 'legend-swatch', style: `background: ${ROAD_USERS[index].color}` }),
            `${ROAD_USERS[index].label}: ${formatNumber(value, 2)} per minute`,
          ]),
          el('span', { className: 'tooltip-muted', text: `${formatNumber(total, 1)} road users per minute in ${row.hours} analysed hours` }),
        );
        tooltip.hidden = false;
        const chartBox = chart.getBoundingClientRect();
        const box = (event.currentTarget || segment).getBoundingClientRect();
        const left = Math.min(Math.max(box.left + box.width / 2 - chartBox.left, 110), chartBox.width - 110);
        tooltip.style.left = `${left}px`;
        tooltip.style.top = `${box.top - chartBox.top}px`;
      };
      segment.addEventListener('mouseenter', show);
      segment.addEventListener('focus', show);
      segment.addEventListener('mouseleave', () => { tooltip.hidden = true; });
      segment.addEventListener('blur', () => { tooltip.hidden = true; });
      return segment;
    }));
    return el('div', { className: `mix-row${row.name === 'All' ? ' is-total' : ''}` }, [
      el('div', { className: 'mix-label', text: row.name === 'All' ? 'World' : row.name }),
      el('div', { className: 'mix-track' }, [bar, el('span', { className: 'mix-total', text: formatNumber(total, 0) })]),
    ]);
  }), tooltip);

  byId('mixTable').replaceChildren(buildTable(table));
}

function buildTable(table, columns = table.headers.map((_, index) => index)) {
  return el('table', {}, [
    el('thead', {}, el('tr', {}, columns.map((index) => el('th', { text: table.headers[index] })))),
    el('tbody', {}, table.rows.map((row) => el('tr', {}, columns.map((index) => el('td', { text: row[index] }))))),
  ]);
}

// ---- Leaderboards ----------------------------------------------------------

function renderLeaderboard({ title, subtitle, items, unit, decimals = 0 }) {
  const max = Math.max(...items.map((item) => item.value));
  return el('article', { className: 'leaderboard-card reveal' }, [
    el('h3', { text: title }),
    el('p', { className: 'viz-sub', text: subtitle }),
    el('ol', { className: 'leaderboard-list' }, items.map((item, index) => el('li', {
      className: 'leaderboard-row',
      title: `${item.name}: ${formatNumber(item.value, decimals)} ${unit}${item.detail ? ` · ${item.detail}` : ''}`,
    }, [
      el('span', { className: 'leaderboard-rank', text: index + 1 }),
      el('span', { className: 'leaderboard-name', text: item.name }),
      el('span', { className: 'leaderboard-value', text: formatNumber(item.value, decimals) }),
      el('span', { className: 'leaderboard-bar', 'aria-hidden': 'true' }, el('span', { style: `width: ${(item.value / max) * 100}%` })),
    ]))),
    el('p', { className: 'leaderboard-unit', text: unit }),
  ]);
}

function renderLeaderboards(countryTable, pedestrianTable, cityTable) {
  const boards = [];
  if (countryTable) {
    const name = tableColumn(countryTable, 'Country');
    const hours = tableColumn(countryTable, 'Footage (h)');
    const cities = tableColumn(countryTable, 'Cities');
    boards.push(renderLeaderboard({
      title: 'Most footage',
      subtitle: 'Countries and territories by hours filmed',
      unit: 'hours of footage',
      items: countryTable.rows.slice(0, 10).map((row) => ({ name: row[name], value: parseNumber(row[hours]), detail: `${row[cities]} cities` })),
    }));
  }
  if (pedestrianTable) {
    const name = tableColumn(pedestrianTable, 'Country');
    const rate = tableColumn(pedestrianTable, 'Pedestrians / min');
    const hours = tableColumn(pedestrianTable, 'Analysed (h)');
    boards.push(renderLeaderboard({
      title: 'Busiest pavements',
      subtitle: 'Pedestrians per minute, 10+ hours analysed',
      unit: 'pedestrians per minute',
      decimals: 1,
      items: pedestrianTable.rows.slice(0, 10).map((row) => ({ name: row[name], value: parseNumber(row[rate]), detail: `${row[hours]} analysed hours` })),
    }));
  }
  if (cityTable) {
    const name = tableColumn(cityTable, 'City');
    const country = tableColumn(cityTable, 'Country');
    const hours = tableColumn(cityTable, 'Footage (h)');
    boards.push(renderLeaderboard({
      title: 'Top cities',
      subtitle: 'Cities and towns by hours filmed',
      unit: 'hours of footage',
      items: cityTable.rows.slice(0, 10).map((row) => ({
        name: `${(row[country].match(/^\S+/) || [''])[0]} ${row[name]}`,
        value: parseNumber(row[hours]),
        detail: row[country],
      })),
    }));
  }
  byId('leaderboardGrid').replaceChildren(...boards);
  boards.forEach(observeReveal);

  if (countryTable) {
    overview.countries = countryTable;
    byId('countryCount').textContent = `${countryTable.rows.length} rows`;
    byId('countrySearch').addEventListener('input', renderCountryTable);
    renderCountryTable();
  } else {
    byId('countryExplorer').hidden = true;
  }
}

function renderCountryTable() {
  const table = overview.countries;
  const query = byId('countrySearch').value.trim().toLowerCase();
  const nameColumn = tableColumn(table, 'Country');
  const { column, ascending } = overview.countrySort;
  const numeric = column !== nameColumn;
  const rows = table.rows
    .filter((row) => row[nameColumn].toLowerCase().includes(query))
    .sort((a, b) => {
      const order = numeric ? parseNumber(a[column]) - parseNumber(b[column]) : a[column].localeCompare(b[column]);
      return ascending ? order : -order;
    });

  const header = el('tr', {}, table.headers.map((name, index) => {
    const button = el('button', { type: 'button', className: 'sort-button', text: name });
    if (index === column) button.dataset.sort = ascending ? 'asc' : 'desc';
    button.addEventListener('click', () => {
      overview.countrySort = { column: index, ascending: index === column ? !ascending : index === nameColumn || index === 0 };
      renderCountryTable();
    });
    return el('th', { 'aria-sort': index === column ? (ascending ? 'ascending' : 'descending') : null }, button);
  }));

  byId('countryTable').replaceChildren(
    el('thead', {}, header),
    el('tbody', {}, rows.map((row) => el('tr', {}, row.map((cell) => el('td', { text: cell }))))),
  );
}

// ---- Figures --------------------------------------------------------------

function openFigure(index) {
  const figures = overview.visibleFigures;
  overview.dialogIndex = (index + figures.length) % figures.length;
  const figure = figures[overview.dialogIndex];
  const dialog = byId('figureDialog');

  byId('figureDialogImage').src = figure.image;
  byId('figureDialogImage').alt = figure.title;
  byId('figureDialogTitle').textContent = figure.title;
  const caption = byId('figureDialogCaption');
  caption.replaceChildren();
  appendInlineMarkdown(caption, figure.caption);
  byId('figureDialogTags').replaceChildren(
    figure.chapter ? el('span', { className: 'figure-card-tag', text: figure.chapter }) : '',
    el('span', { className: 'figure-count', text: `${overview.dialogIndex + 1} / ${figures.length}` }),
  );
  byId('figureDialogInteractive').href = figure.interactiveUrl;
  byId('figureDialogImageLink').href = figure.image;
  if (!dialog.open) dialog.showModal();
}

function setupFigureDialog() {
  const dialog = byId('figureDialog');
  byId('figureDialogClose').addEventListener('click', () => dialog.close());
  byId('figurePrev').addEventListener('click', () => openFigure(overview.dialogIndex - 1));
  byId('figureNext').addEventListener('click', () => openFigure(overview.dialogIndex + 1));
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) dialog.close();
  });
  dialog.addEventListener('keydown', (event) => {
    if (event.key === 'ArrowLeft') openFigure(overview.dialogIndex - 1);
    if (event.key === 'ArrowRight') openFigure(overview.dialogIndex + 1);
  });
}

function renderFigures(figures, stats) {
  if (!figures.length) {
    byId('figureChapters').replaceChildren(el('div', { className: 'empty-note' }, [
      'The figures could not be loaded just now. See them on the ',
      el('a', { href: CROWD_REPO_URL, target: '_blank', rel: 'noreferrer noopener', text: 'project page' }),
      '.',
    ]));
    return;
  }
  renderFigureStory(figures);
}

// ---- Curation and contributors ---------------------------------------------

function renderAcknowledgement(table, markdown) {
  const reviewed = markdown.match(/In total, ([\d,]+) cuts were analysed/)?.[1];
  if (reviewed) byId('cutsReviewed').textContent = reviewed;

  const column = table ? tableColumn(table, 'Contributor') : -1;
  const names = column >= 0 ? table.rows.map((row) => row[column]).filter(Boolean) : [];
  if (!names.length) return;
  const list = names.length > 1 ? `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}` : names[0];
  byId('acknowledgementText').textContent = `We thank everyone who found, selected and checked footage for CROWD: ${list}.`;
}

// ---- Reveal on scroll -------------------------------------------------------

let revealObserver = null;

function observeReveal(node) {
  if (!revealObserver) return;
  revealObserver.observe(node);
}

function setupReveal() {
  if (prefersReducedMotion || !('IntersectionObserver' in window)) return;
  document.documentElement.classList.add('js-reveal');
  revealObserver = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add('is-visible');
      revealObserver.unobserve(entry.target);
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
  document.querySelectorAll('.reveal').forEach(observeReveal);
}

// ---- Main -------------------------------------------------------------------

function showReadmeError() {
  byId('liveNote').textContent = 'The latest numbers could not be loaded just now; showing the paper release.';
  const message = el('div', { className: 'empty-note' }, [
    'This part of the page could not be loaded just now. Please try again in a moment, or see the ',
    el('a', { href: CROWD_REPO_URL, target: '_blank', rel: 'noreferrer noopener', text: 'project page' }),
    '.',
  ]);
  byId('figureChapters').replaceChildren(message);
  byId('detectionGrid').replaceChildren(message.cloneNode(true));
}

async function mainOverview() {
  setupReveal();
  setupFigureDialog();

  let markdown;
  try {
    const response = await fetch(README_URL, { cache: 'no-cache' });
    if (!response.ok) throw new Error(`README request failed: ${response.status}`);
    markdown = await response.text();
  } catch (error) {
    console.error(error);
    showReadmeError();
    return;
  }

  const stats = parseStats(markdown);
  const figures = parseFigures(markdown);
  if (stats.hours) renderLiveStats(stats);
  renderDetections(stats, parseTableAfter(markdown, 'Detections per continent'), markdown);
  renderLeaderboards(
    parseTableAfter(markdown, '<summary><b>All '),
    parseTableAfter(markdown, 'Top 20 countries by pedestrians per minute'),
    parseTableAfter(markdown, 'Top 200 cities by footage'),
  );
  renderFigures(figures, stats);
  renderAcknowledgement(parseTableAfter(markdown, '<!-- contributors:start -->'), markdown);

  // A link such as #figures was followed before the sections above filled in and moved it down;
  // go there again now that the page has its final layout.
  const target = location.hash && document.getElementById(decodeURIComponent(location.hash.slice(1)));
  if (target) requestAnimationFrame(() => target.scrollIntoView());
}

mainOverview();
